"use client"

import { useEffect, useMemo, useState } from "react"
import Link from "next/link"
import { ArrowLeft, CheckCircle2, CreditCard, Download, Eye, FileCode2, FilterX, Package, Plus, Printer, RotateCcw, Save, Search, Send, ShieldCheck, ShoppingCart, Trash2, X } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Textarea } from "@/components/ui/textarea"
import { initialProductMaster, ProductMaster, PRODUCT_STORAGE_KEY } from "@/lib/product-master"

export type ElectronicDocumentKind = "pos" | "invoice" | "pos-return" | "invoice-return"
type Line = { id: string; productId: string; code: string; description: string; unitCode: string; quantity: number; unitPrice: number; discount: number; taxRate: number }
type Customer = { idType: string; id: string; dv: string; name: string; email: string; phone: string; address: string; cityCode: string; fiscalResponsibility: string; taxRegime: string }
type BillingRecord = { id: string; kind: ElectronicDocumentKind; number: string; prefix: string; date: string; time: string; customer: Customer; lines: Line[]; paymentForm: string; paymentMethod: string; dueDate: string; currency: string; notes: string; status: string; uniqueCode: string; originalNumber: string; originalCode: string; returnReason: string; createdAt: string }

const company = { name: "FERREIA S.A.S.", nit: "900123456", dv: "7", address: "Calle 20 # 10-25", city: "Bogotá D.C.", cityCode: "11001", phone: "+57 601 555 0101", email: "facturacion@ferreia.co", responsibility: "R-99-PN", regime: "Responsable de IVA" }
const configuration = { invoice: { prefix: "FEV", resolution: "187640000001", range: "1 a 5.000", validUntil: "2027-12-31" }, pos: { prefix: "DE", resolution: "187640000002", range: "1 a 10.000", validUntil: "2027-12-31" }, softwareId: "Configurar en integración DIAN", environment: "Habilitación / pruebas" }
const today = () => new Date().toISOString().slice(0, 10)
const now = () => new Date().toTimeString().slice(0, 8)
const emptyCustomer: Customer = { idType: "13", id: "222222222222", dv: "", name: "Consumidor final", email: "", phone: "", address: "", cityCode: "11001", fiscalResponsibility: "R-99-PN", taxRegime: "No responsable de IVA" }
const settings = {
  pos: { title: "Facturación POS electrónica", documentName: "Documento equivalente electrónico POS", prefix: configuration.pos.prefix, code: "CUDE", return: false, source: "" },
  invoice: { title: "Factura electrónica de venta", documentName: "Factura electrónica de venta", prefix: configuration.invoice.prefix, code: "CUFE", return: false, source: "" },
  "pos-return": { title: "Devolución POS electrónica", documentName: "Nota de ajuste al documento equivalente electrónico POS", prefix: "NAP", code: "CUDE", return: true, source: "Documento POS origen" },
  "invoice-return": { title: "Devolución de factura electrónica", documentName: "Nota crédito electrónica", prefix: "NC", code: "CUDE", return: true, source: "Factura electrónica origen" },
} as const

export function ElectronicBillingView({ kind }: { kind: ElectronicDocumentKind }) {
  const cfg = settings[kind]; const storageKey = `ferreia-electronic-documents-${kind}`
  const [products, setProducts] = useState(initialProductMaster); const [records, setRecords] = useState<BillingRecord[]>([])
  const [customer, setCustomer] = useState<Customer>(emptyCustomer); const [lines, setLines] = useState<Line[]>([]); const [query, setQuery] = useState(""); const [selected, setSelected] = useState(""); const [selectedLineId, setSelectedLineId] = useState(""); const [productSearchOpen, setProductSearchOpen] = useState(false)
  const [date, setDate] = useState(today()); const [time, setTime] = useState(now()); const [paymentForm, setPaymentForm] = useState("1"); const [paymentMethod, setPaymentMethod] = useState("10"); const [dueDate, setDueDate] = useState(today()); const [currency, setCurrency] = useState("COP"); const [notes, setNotes] = useState("")
  const [seller, setSeller] = useState(""); const [warehouse, setWarehouse] = useState("Bodega Principal"); const [externalNumber, setExternalNumber] = useState(""); const [priceList, setPriceList] = useState("GENERAL"); const [globalDiscount, setGlobalDiscount] = useState(0); const [surcharge, setSurcharge] = useState(0); const [referenceType, setReferenceType] = useState("Orden de compra"); const [referenceNumber, setReferenceNumber] = useState(""); const [otherConcept, setOtherConcept] = useState(""); const [withholdingRate, setWithholdingRate] = useState(0)
  const [originalNumber, setOriginalNumber] = useState(""); const [originalCode, setOriginalCode] = useState(""); const [returnReason, setReturnReason] = useState("1"); const [error, setError] = useState(""); const [saved, setSaved] = useState(false); const [preview, setPreview] = useState<BillingRecord | null>(null)
  const [historyQuery, setHistoryQuery] = useState(""); const [historyStatus, setHistoryStatus] = useState("todos"); const [from, setFrom] = useState(""); const [to, setTo] = useState("")
  const [posInvoices, setPosInvoices] = useState<BillingRecord[]>([]); const [crossOpen, setCrossOpen] = useState(false); const [crossQuery, setCrossQuery] = useState(""); const [payments, setPayments] = useState([{ method: "10", amount: 0 }, { method: "48", amount: 0 }, { method: "47", amount: 0 }, { method: "ZZZ", amount: 0 }])
  useEffect(() => { const p = localStorage.getItem(PRODUCT_STORAGE_KEY); const r = localStorage.getItem(storageKey); if (p) setProducts(JSON.parse(p)); if (r) setRecords(JSON.parse(r)) }, [storageKey])
  useEffect(() => { if (kind === "pos-return") { const raw = localStorage.getItem("ferreia-electronic-documents-pos"); setPosInvoices(raw ? JSON.parse(raw) : []) } }, [kind, records])
  const number = String(records.length + 1).padStart(8, "0")
  const filteredProducts = useMemo(() => { const q = query.trim().toLowerCase(); return products.filter((p) => p.active && (!q || [p.reference, p.supplierReference, p.sku, p.name, p.brand, p.line, p.group, p.subgroup, ...p.barcodes.map((b) => b.code)].some((v) => v.toLowerCase().includes(q)))) }, [products, query])
  const subtotal = lines.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0); const discounts = lines.reduce((sum, l) => sum + l.quantity * l.unitPrice * l.discount / 100, 0); const taxes = lines.reduce((sum, l) => sum + l.quantity * l.unitPrice * (1 - l.discount / 100) * l.taxRate / 100, 0); const total = subtotal - discounts + taxes
  const history = useMemo(() => { const q = historyQuery.trim().toLowerCase(); return [...records].reverse().filter((r) => (!q || [r.prefix + r.number, r.customer.id, r.customer.name, r.originalNumber].some((v) => v.toLowerCase().includes(q))) && (historyStatus === "todos" || r.status === historyStatus) && (!from || r.date >= from) && (!to || r.date <= to)) }, [records, historyQuery, historyStatus, from, to])
  function addProductById(productId: string) { const p = products.find((item) => item.id === productId); if (!p) return; const existing = lines.find((line) => line.productId === p.id); if (existing) { setSelectedLineId(existing.id); setLines((current) => current.map((line) => line.id === existing.id ? { ...line, quantity: line.quantity + 1 } : line)) } else { const line = { id: crypto.randomUUID(), productId: p.id, code: p.reference, description: p.name, unitCode: "94", quantity: 1, unitPrice: p.price, discount: 0, taxRate: p.taxRate }; setLines((current) => [...current, line]); setSelectedLineId(line.id) } setSelected(""); setQuery(""); setProductSearchOpen(false); setSaved(false) }
  function addProduct() { if (selected) addProductById(selected) }
  function patchLine(id: string, patch: Partial<Line>) { setLines(lines.map((line) => line.id === id ? { ...line, ...patch } : line)); setSaved(false) }
  function makeCode() { const text = `${cfg.prefix}${number}|${date}|${time}|${company.nit}|${customer.id}|${total.toFixed(2)}`; let hash = 2166136261; for (let i = 0; i < text.length; i++) hash = Math.imul(hash ^ text.charCodeAt(i), 16777619); return Array.from({ length: 4 }, (_, i) => Math.abs(hash + i * 2654435761).toString(16).padStart(8, "0")).join("").toUpperCase() }
  function buildRecord(status = "Borrador"): BillingRecord { return { id: crypto.randomUUID(), kind, number, prefix: cfg.prefix, date, time, customer, lines, paymentForm, paymentMethod, dueDate, currency, notes, status, uniqueCode: makeCode(), originalNumber, originalCode, returnReason, createdAt: new Date().toISOString() } }
  function validate() { if (!customer.id.trim() || !customer.name.trim()) return "Completa la identificación y nombre del adquirente."; if (!lines.length) return "Agrega al menos un artículo o servicio."; if (lines.some((l) => l.quantity <= 0 || l.unitPrice < 0)) return "Verifica cantidades y valores del detalle."; if (cfg.return && (!originalNumber.trim() || !originalCode.trim())) return `Relaciona el ${cfg.source.toLowerCase()} y su código electrónico.`; return "" }
  function save(status = "Borrador") { const message = validate(); if (message) { setError(message); return } const record = buildRecord(status); const next = [...records, record]; setRecords(next); localStorage.setItem(storageKey, JSON.stringify(next)); setSaved(true); setError(""); setPreview(record) }
  function transmit() { save("Pendiente de envío DIAN") }
  function reset() { setCustomer(emptyCustomer); setLines([]); setSelectedLineId(""); setNotes(""); setOriginalNumber(""); setOriginalCode(""); setReturnReason("1"); setSaved(false); setError(""); setPreview(null) }
  function selectPosInvoice(record: BillingRecord) { const copied = record.lines.map((line) => ({ ...line, id: crypto.randomUUID() })); setCustomer(record.customer); setLines(copied); setSelectedLineId(copied[0]?.id ?? ""); setOriginalNumber(`${record.prefix}-${record.number}`); setOriginalCode(record.uniqueCode); setPaymentForm(record.paymentForm); setPaymentMethod(record.paymentMethod); setNotes(`Devolución relacionada con ${record.prefix}-${record.number}`); setCrossOpen(false); setSaved(false); setError("") }
  if (kind === "pos" || kind === "pos-return") return <PosWorkspace kind={kind} cfg={cfg} number={number} date={date} setDate={setDate} customer={customer} setCustomer={setCustomer} seller={seller} setSeller={setSeller} warehouse={warehouse} setWarehouse={setWarehouse} priceList={priceList} setPriceList={setPriceList} query={query} setQuery={setQuery} products={filteredProducts} allProducts={products} productSearchOpen={productSearchOpen} setProductSearchOpen={setProductSearchOpen} addProductById={addProductById} lines={lines} selectedLineId={selectedLineId} setSelectedLineId={setSelectedLineId} patchLine={patchLine} removeLine={(id) => { setLines(lines.filter((line) => line.id !== id)); if (selectedLineId === id) setSelectedLineId(lines.find((line) => line.id !== id)?.id ?? "") }} subtotal={subtotal} discounts={discounts} taxes={taxes} total={total} payments={payments} setPayments={setPayments} error={error} saved={saved} reset={reset} save={save} transmit={transmit} history={history} historyQuery={historyQuery} setHistoryQuery={setHistoryQuery} historyStatus={historyStatus} setHistoryStatus={setHistoryStatus} from={from} setFrom={setFrom} to={to} setTo={setTo} setPreview={setPreview} preview={preview} crossOpen={crossOpen} setCrossOpen={setCrossOpen} crossQuery={crossQuery} setCrossQuery={setCrossQuery} posInvoices={posInvoices} selectPosInvoice={selectPosInvoice} originalNumber={originalNumber} returnReason={returnReason} setReturnReason={setReturnReason} />
  return <div className="space-y-5">
    <Button asChild variant="ghost" size="sm"><Link href="/admin/movimientos"><ArrowLeft className="mr-2 h-4 w-4" />Volver</Link></Button>
    <div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-start"><div><div className="flex flex-wrap items-center gap-2"><h1 className="text-2xl font-bold">{cfg.title}</h1><Badge variant="secondary" className="bg-cyan-50 text-cyan-800">DIAN · {cfg.code}</Badge><Badge variant="outline">{configuration.environment}</Badge></div><p className="mt-1 text-sm text-muted-foreground">Generación, representación gráfica, trazabilidad y preparación para validación previa.</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={reset}><Plus className="mr-2 h-4 w-4" />Nuevo</Button><Button variant="outline" onClick={() => save()} disabled={saved}><Save className="mr-2 h-4 w-4" />Guardar borrador</Button><Button onClick={transmit} disabled={saved}><Send className="mr-2 h-4 w-4" />Generar documento</Button></div></div>
    <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900"><b>Entorno local:</b> el documento queda preparado y marcado como pendiente. La validación real exige credenciales, certificado digital, software habilitado y servicio DIAN/proveedor tecnológico.</div>
    {error && <div className="rounded-lg bg-rose-50 p-3 text-sm text-rose-800">{error}</div>}
    {kind === "invoice" && <Card><CardContent className="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-4"><Field label="Fecha"><Input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></Field><Field label="Factura No."><Input value={`${cfg.prefix}-${number}`} disabled /></Field><Field label="No. externo"><Input value={externalNumber} onChange={(e) => setExternalNumber(e.target.value)} placeholder="Orden o consecutivo externo" /></Field><Field label="Bodega"><SelectField value={warehouse} setValue={setWarehouse} options={[["Bodega Principal", "Bodega Principal"], ["Bodega Norte", "Bodega Norte"], ["Bodega Sur", "Bodega Sur"], ["Mostrador", "Mostrador"]]} /></Field><Field label="Cliente / identificación"><Input value={customer.id} onChange={(e) => setCustomer({ ...customer, id: e.target.value })} placeholder="NIT o documento" /></Field><Field label="Nombre o razón social" wide><Input value={customer.name} onChange={(e) => setCustomer({ ...customer, name: e.target.value })} /></Field><Field label="Vendedor"><Input value={seller} onChange={(e) => setSeller(e.target.value)} placeholder="Seleccionar vendedor" /></Field><Field label="Lista de precios"><SelectField value={priceList} setValue={setPriceList} options={[["GENERAL", "GENERAL"], ["MAYORISTA", "MAYORISTA"], ["DISTRIBUIDOR", "DISTRIBUIDOR"]]} /></Field><Field label="Detalle comercial" wide><Input value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Observación general de la venta" /></Field></CardContent></Card>}
    <Tabs defaultValue={kind === "invoice" ? "detalle" : "documento"} className="space-y-4"><TabsList className="h-auto flex-wrap"><TabsTrigger value="documento">{kind === "invoice" ? "Encabezado" : "1. Documento"}</TabsTrigger><TabsTrigger value="adquirente">{kind === "invoice" ? "Cliente" : "2. Adquirente"}</TabsTrigger><TabsTrigger value="detalle">{kind === "invoice" ? "Inventarios/Servicios" : "3. Productos y servicios"}</TabsTrigger><TabsTrigger value="pago">{kind === "invoice" ? "Formas de pago" : "4. Pago y totales"}</TabsTrigger>{kind === "invoice" && <><TabsTrigger value="ajustes">Recargos/Desctos.</TabsTrigger><TabsTrigger value="referencias">Doc. referenciados</TabsTrigger><TabsTrigger value="otros">Otros conceptos</TabsTrigger><TabsTrigger value="impuestos">Impuestos/Retenciones</TabsTrigger></>}<TabsTrigger value="dian">{kind === "invoice" ? "+Info" : "5. Información DIAN"}</TabsTrigger></TabsList>
      <TabsContent value="documento"><Card><CardContent className="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-4"><Field label="Tipo de documento"><Input value={cfg.documentName} disabled /></Field><Field label="Consecutivo"><Input value={`${cfg.prefix}-${number}`} disabled /></Field><Field label="Fecha de emisión"><Input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></Field><Field label="Hora de emisión"><Input type="time" step="1" value={time} onChange={(e) => setTime(e.target.value)} /></Field>{cfg.return && <><Field label={`${cfg.source} *`}><Input value={originalNumber} onChange={(e) => setOriginalNumber(e.target.value)} placeholder="Prefijo y número" /></Field><Field label={`${kind === "invoice-return" ? "CUFE" : "CUDE"} del documento origen *`} wide><Input value={originalCode} onChange={(e) => setOriginalCode(e.target.value)} placeholder="Código único del documento afectado" /></Field><Field label="Concepto de corrección"><SelectField value={returnReason} setValue={setReturnReason} options={kind === "invoice-return" ? [["1", "Devolución parcial"], ["2", "Anulación"], ["3", "Rebaja o descuento"], ["4", "Ajuste de precio"], ["5", "Otros"]] : [["1", "Anulación"], ["2", "Corrección de datos"], ["3", "Devolución parcial"], ["4", "Otros"]]} /></Field></>}<Field label="Observaciones" wide><Textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Orden de compra, vendedor, condiciones o motivo detallado" /></Field></CardContent></Card></TabsContent>
      <TabsContent value="adquirente"><Card><CardContent className="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-4"><Field label="Tipo de identificación"><SelectField value={customer.idType} setValue={(v) => setCustomer({ ...customer, idType: v })} options={[["13", "Cédula de ciudadanía"], ["31", "NIT"], ["22", "Cédula de extranjería"], ["41", "Pasaporte"], ["42", "Documento extranjero"], ["43", "Sin identificación del exterior"]]} /></Field><Field label="Número de identificación *"><Input value={customer.id} onChange={(e) => setCustomer({ ...customer, id: e.target.value })} /></Field><Field label="DV"><Input maxLength={1} value={customer.dv} onChange={(e) => setCustomer({ ...customer, dv: e.target.value })} /></Field><Field label="Nombre o razón social *"><Input value={customer.name} onChange={(e) => setCustomer({ ...customer, name: e.target.value })} /></Field><Field label="Correo electrónico"><Input type="email" value={customer.email} onChange={(e) => setCustomer({ ...customer, email: e.target.value })} /></Field><Field label="Teléfono"><Input value={customer.phone} onChange={(e) => setCustomer({ ...customer, phone: e.target.value })} /></Field><Field label="Dirección"><Input value={customer.address} onChange={(e) => setCustomer({ ...customer, address: e.target.value })} /></Field><Field label="Código municipio DANE"><Input value={customer.cityCode} onChange={(e) => setCustomer({ ...customer, cityCode: e.target.value })} /></Field><Field label="Responsabilidad fiscal"><Input value={customer.fiscalResponsibility} onChange={(e) => setCustomer({ ...customer, fiscalResponsibility: e.target.value })} placeholder="Ej. O-13, O-15, R-99-PN" /></Field><Field label="Régimen tributario"><SelectField value={customer.taxRegime} setValue={(v) => setCustomer({ ...customer, taxRegime: v })} options={[["Responsable de IVA", "Responsable de IVA"], ["No responsable de IVA", "No responsable de IVA"]]} /></Field></CardContent></Card></TabsContent>
      <TabsContent value="detalle" className="space-y-3"><Card><CardContent className="p-4"><button type="button" onClick={() => setProductSearchOpen(true)} className="flex w-full items-center gap-3 rounded-lg border border-input bg-background px-4 py-3 text-left transition-colors hover:border-primary/50 hover:bg-muted/40"><Search className="h-5 w-5 text-primary" /><span className="flex-1"><b className="block text-sm">Buscar y adicionar productos o servicios</b><span className="text-xs text-muted-foreground">Referencia, descripción, SKU, marca o código de barras</span></span><Plus className="h-5 w-5 text-muted-foreground" /></button></CardContent></Card><LineTable lines={lines} patchLine={patchLine} remove={(id) => setLines(lines.filter((l) => l.id !== id))} /></TabsContent>
      <TabsContent value="pago"><div className="grid gap-4 lg:grid-cols-[1fr_360px]"><Card><CardContent className="grid gap-4 p-5 md:grid-cols-2"><Field label="Forma de pago"><SelectField value={paymentForm} setValue={setPaymentForm} options={[["1", "Contado"], ["2", "Crédito"]]} /></Field><Field label="Medio de pago"><SelectField value={paymentMethod} setValue={setPaymentMethod} options={[["10", "Efectivo"], ["42", "Consignación bancaria"], ["47", "Transferencia débito"], ["48", "Tarjeta crédito"], ["49", "Tarjeta débito"], ["ZZZ", "Otro"]]} /></Field>{paymentForm === "2" && <Field label="Fecha de vencimiento"><Input type="date" value={dueDate} onChange={(e) => setDueDate(e.target.value)} /></Field>}<Field label="Moneda"><SelectField value={currency} setValue={setCurrency} options={[["COP", "Peso colombiano (COP)"], ["USD", "Dólar estadounidense (USD)"], ["EUR", "Euro (EUR)"]]} /></Field></CardContent></Card><Totals subtotal={subtotal} discounts={discounts} taxes={taxes} total={total} /></div></TabsContent>
      {kind === "invoice" && <><TabsContent value="ajustes"><Card><CardContent className="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-4"><Field label="Descuento global %"><Input type="number" min="0" max="100" value={globalDiscount} onChange={(e) => setGlobalDiscount(Number(e.target.value))} /></Field><Field label="Recargo global $"><Input type="number" min="0" value={surcharge} onChange={(e) => setSurcharge(Number(e.target.value))} /></Field><Field label="Motivo del descuento/recargo" wide><Textarea placeholder="Justificación comercial del ajuste" /></Field></CardContent></Card></TabsContent><TabsContent value="referencias"><Card><CardContent className="grid gap-4 p-5 md:grid-cols-2"><Field label="Tipo de documento"><SelectField value={referenceType} setValue={setReferenceType} options={[["Orden de compra", "Orden de compra"], ["Pedido", "Pedido"], ["Remisión", "Remisión"], ["Cotización", "Cotización"], ["Contrato", "Contrato"]]} /></Field><Field label="Número referenciado"><Input value={referenceNumber} onChange={(e) => setReferenceNumber(e.target.value)} placeholder="Prefijo y número" /></Field></CardContent></Card></TabsContent><TabsContent value="otros"><Card><CardContent className="p-5"><Field label="Otros conceptos de la operación" wide><Textarea value={otherConcept} onChange={(e) => setOtherConcept(e.target.value)} placeholder="Fletes, seguros, anticipos u otros cargos informativos" /></Field></CardContent></Card></TabsContent><TabsContent value="impuestos"><Card><CardContent className="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-4"><DianItem label="IVA calculado" value={`$${money(taxes)}`} /><Field label="Retención en la fuente %"><Input type="number" min="0" step="0.01" value={withholdingRate} onChange={(e) => setWithholdingRate(Number(e.target.value))} /></Field><DianItem label="Base gravable" value={`$${money(subtotal - discounts)}`} /><DianItem label="Total estimado con ajustes" value={`$${money(total - total * globalDiscount / 100 + surcharge - (subtotal - discounts) * withholdingRate / 100)}`} /></CardContent></Card></TabsContent></>}
      <TabsContent value="dian"><Card><CardContent className="grid gap-5 p-5 md:grid-cols-2 xl:grid-cols-3"><DianItem label="Emisor" value={`${company.name} · NIT ${company.nit}-${company.dv}`} /><DianItem label="Numeración autorizada" value={`${cfg.prefix} · ${kind.includes("pos") ? configuration.pos.resolution : configuration.invoice.resolution}`} /><DianItem label="Rango y vigencia" value={`${kind.includes("pos") ? configuration.pos.range : configuration.invoice.range} · hasta ${kind.includes("pos") ? configuration.pos.validUntil : configuration.invoice.validUntil}`} /><DianItem label="Anexo técnico" value={kind.includes("pos") ? "Documento equivalente electrónico v1.0" : "Factura electrónica de venta v1.9"} /><DianItem label="Software DIAN" value={configuration.softwareId} warning /><DianItem label="Firma digital" value="Pendiente de certificado e integración" warning /></CardContent></Card></TabsContent>
    </Tabs>
    <History records={history} query={historyQuery} setQuery={setHistoryQuery} status={historyStatus} setStatus={setHistoryStatus} from={from} setFrom={setFrom} to={to} setTo={setTo} reset={() => { setHistoryQuery(""); setHistoryStatus("todos"); setFrom(""); setTo("") }} preview={setPreview} />
    {preview && <DocumentPreview record={preview} close={() => setPreview(null)} />}
    {productSearchOpen && <ProductSearchModal products={filteredProducts} query={query} setQuery={setQuery} add={addProductById} close={() => { setProductSearchOpen(false); setQuery("") }} />}
  </div>
}

type PosWorkspaceProps = {
  kind: "pos" | "pos-return"; cfg: (typeof settings)[keyof typeof settings]; number: string; date: string; setDate: (value: string) => void
  customer: Customer; setCustomer: React.Dispatch<React.SetStateAction<Customer>>; seller: string; setSeller: (value: string) => void; warehouse: string; setWarehouse: (value: string) => void; priceList: string; setPriceList: (value: string) => void
  query: string; setQuery: (value: string) => void; products: ProductMaster[]; allProducts: ProductMaster[]; productSearchOpen: boolean; setProductSearchOpen: (value: boolean) => void; addProductById: (id: string) => void; lines: Line[]; selectedLineId: string; setSelectedLineId: (value: string) => void; patchLine: (id: string, patch: Partial<Line>) => void; removeLine: (id: string) => void
  subtotal: number; discounts: number; taxes: number; total: number; payments: { method: string; amount: number }[]; setPayments: React.Dispatch<React.SetStateAction<{ method: string; amount: number }[]>>
  error: string; saved: boolean; reset: () => void; save: (status?: string) => void; transmit: () => void; history: BillingRecord[]; historyQuery: string; setHistoryQuery: (value: string) => void; historyStatus: string; setHistoryStatus: (value: string) => void; from: string; setFrom: (value: string) => void; to: string; setTo: (value: string) => void
  setPreview: (record: BillingRecord | null) => void; preview: BillingRecord | null; crossOpen: boolean; setCrossOpen: (value: boolean) => void; crossQuery: string; setCrossQuery: (value: string) => void; posInvoices: BillingRecord[]; selectPosInvoice: (record: BillingRecord) => void; originalNumber: string; returnReason: string; setReturnReason: (value: string) => void
}

function PosWorkspace(p: PosWorkspaceProps) {
  const isReturn = p.kind === "pos-return"; const paid = p.payments.reduce((sum, payment) => sum + payment.amount, 0); const change = Math.max(0, paid - p.total); const activeLine = p.lines.find((line) => line.id === p.selectedLineId) ?? p.lines[0]; const activeProduct = activeLine ? p.allProducts.find((product) => product.id === activeLine.productId) : undefined; const activeImage = activeProduct?.images.find(Boolean)
  function patchPayment(index: number, patch: Partial<{ method: string; amount: number }>) { p.setPayments((items) => items.map((item, current) => current === index ? { ...item, ...patch } : item)) }
  return <div className="space-y-4">
    <Button asChild variant="ghost" size="sm"><Link href="/admin/movimientos"><ArrowLeft className="mr-2 h-4 w-4" />Volver a movimientos</Link></Button>
    <Card className="overflow-hidden border-0 shadow-lg"><div className={`grid lg:grid-cols-[360px_1fr] ${isReturn ? "bg-amber-500" : "bg-cyan-500"}`}><div className="bg-white p-5"><div className="flex items-center gap-2"><ShoppingCart className="h-6 w-6 text-primary" /><h1 className="text-xl font-black">{isReturn ? "DEVOLUCIÓN EN VENTA POS" : "FACTURA DE VENTA POS"}</h1></div><p className="mt-1 text-sm text-muted-foreground">{p.cfg.documentName}</p><p className="mt-2 text-sm">No. <b className="font-mono text-rose-600">{p.cfg.prefix}-{p.number}</b></p><div className="mt-4 grid grid-cols-[70px_1fr] gap-x-2 gap-y-1 text-xs"><span className="text-muted-foreground">Usuario:</span><b>{p.seller || "Cajero principal"}</b><span className="text-muted-foreground">Bodega:</span><b>{p.warehouse}</b><span className="text-muted-foreground">Precios:</span><b>{p.priceList}</b>{isReturn && <><span className="text-muted-foreground">Factura:</span><b className="text-amber-700">{p.originalNumber || "Sin relacionar"}</b></>}</div></div><div className="grid min-h-48 items-center gap-5 p-5 text-slate-950 md:grid-cols-[190px_1fr_auto]"><div className="flex h-40 items-center justify-center overflow-hidden rounded-xl border border-white/60 bg-white/90 shadow-sm">{activeImage ? <img src={activeImage} alt={activeLine?.description ?? "Producto seleccionado"} className="h-full w-full object-contain p-2" /> : <div className="text-center text-slate-500"><Package className="mx-auto mb-2 h-12 w-12 opacity-50" /><p className="text-xs font-semibold">{activeLine ? "Artículo sin imagen" : "Selecciona un artículo"}</p></div>}</div><div className="min-w-0">{activeLine ? <><Badge className="mb-2 bg-white/80 text-slate-800" variant="secondary">Artículo seleccionado</Badge><p className="truncate text-2xl font-black">{activeLine.description}</p><p className="mt-1 font-mono text-sm">Ref. {activeLine.code}</p><div className="mt-4 flex flex-wrap gap-4 text-sm"><span>Cantidad: <b>{activeLine.quantity}</b></span><span>Vr. unitario: <b>${money(activeLine.unitPrice)}</b></span><span>Dto.: <b>{activeLine.discount}%</b></span></div></> : <p className="text-sm font-semibold">Los productos adicionados aparecerán en este visor.</p>}</div><div className="text-right"><div className="mb-4 grid grid-cols-2 gap-x-8 gap-y-1 text-xs"><span>Subtotal</span><b className="text-right">${money(p.subtotal)}</b><span>Descuentos</span><b className="text-right">-${money(p.discounts)}</b><span>IVA</span><b className="text-right">${money(p.taxes)}</b></div><p className="text-xs font-bold uppercase">Total {isReturn ? "a devolver" : "de la venta"}</p><p className="text-5xl font-black tracking-tight">${money(p.total)}</p><p className="mt-1 text-sm">{p.lines.reduce((sum, line) => sum + line.quantity, 0)} unidades</p></div></div></div>
      <CardContent className="space-y-4 p-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5"><Field label="Fecha"><Input type="date" value={p.date} onChange={(e) => p.setDate(e.target.value)} /></Field><Field label="Vendedor"><Input value={p.seller} onChange={(e) => p.setSeller(e.target.value)} placeholder="Cajero o vendedor" /></Field><Field label="Bodega"><SelectField value={p.warehouse} setValue={p.setWarehouse} options={[["Bodega Principal", "Bodega Principal"], ["Bodega Norte", "Bodega Norte"], ["Bodega Sur", "Bodega Sur"], ["Mostrador", "Mostrador"]]} /></Field><Field label="Lista de precios"><SelectField value={p.priceList} setValue={p.setPriceList} options={[["GENERAL", "GENERAL"], ["MAYORISTA", "MAYORISTA"], ["DISTRIBUIDOR", "DISTRIBUIDOR"]]} /></Field><Field label="NIT / C.C."><div className="flex gap-2"><Input value={p.customer.id} onChange={(e) => p.setCustomer({ ...p.customer, id: e.target.value })} />{isReturn && <Button className="shrink-0 bg-amber-500 text-slate-950 hover:bg-amber-600" onClick={() => p.setCrossOpen(true)} title="Cruzar factura POS">D</Button>}</div></Field><Field label="Cliente" wide><Input value={p.customer.name} onChange={(e) => p.setCustomer({ ...p.customer, name: e.target.value })} /></Field>{isReturn && <Field label="Causal de devolución"><SelectField value={p.returnReason} setValue={p.setReturnReason} options={[["1", "Anulación"], ["2", "Corrección de datos"], ["3", "Devolución parcial"], ["4", "Otros"]]} /></Field>}</div>
      <button type="button" onClick={() => p.setProductSearchOpen(true)} className="flex w-full items-center gap-3 rounded-lg border border-input bg-background px-4 py-3 text-left transition-colors hover:border-primary/50 hover:bg-muted/40"><Search className="h-5 w-5 text-primary" /><span className="flex-1"><b className="block text-sm">Buscar producto para facturar</b><span className="text-xs text-muted-foreground">Haz clic para buscar en tiempo real por referencia, descripción o código de barras</span></span><Plus className="h-5 w-5 text-muted-foreground" /></button>
      <PosLineTable lines={p.lines} selectedLineId={p.selectedLineId} selectLine={p.setSelectedLineId} patchLine={p.patchLine} remove={p.removeLine} />
      <div className="grid gap-4 xl:grid-cols-[1fr_500px]"><div className="flex flex-wrap content-start gap-2"><Button onClick={() => p.save()} disabled={p.saved}><Save className="mr-2 h-4 w-4" />Grabar</Button><Button variant="outline" onClick={p.reset}><Plus className="mr-2 h-4 w-4" />Nueva</Button><Button variant="outline" onClick={() => p.lines.length && p.removeLine(p.lines[p.lines.length - 1].id)} disabled={!p.lines.length}><Trash2 className="mr-2 h-4 w-4" />Quitar</Button><Button variant="outline" onClick={() => p.preview && printRecord(p.preview)} disabled={!p.preview}><Printer className="mr-2 h-4 w-4" />Reimprimir</Button><Button onClick={p.transmit} disabled={p.saved}><Send className="mr-2 h-4 w-4" />Enviar DIAN</Button></div><Card className="bg-muted/20"><CardContent className="space-y-2 p-4"><div className="mb-3 flex items-center gap-2 font-bold"><CreditCard className="h-4 w-4" />Formas de pago</div>{p.payments.map((payment, index) => <div key={index} className="grid grid-cols-[24px_1fr_170px] items-center gap-2"><span className="text-xs">{index + 1}.</span><Input className="text-right font-semibold" type="number" min="0" value={payment.amount} onChange={(e) => patchPayment(index, { amount: Number(e.target.value) })} /><SelectField value={payment.method} setValue={(value) => patchPayment(index, { method: value })} options={[["10", "Efectivo"], ["48", "Tarjeta crédito"], ["49", "Tarjeta débito"], ["47", "Transferencia"], ["ZZZ", "Otro"]]} /></div>)}<div className="mt-3 flex justify-between border-t pt-3"><span>Recibido: <b>${money(paid)}</b></span><span>Cambio: <b className="text-lg text-emerald-700">${money(change)}</b></span></div></CardContent></Card></div>
      {p.error && <div className="rounded-lg bg-rose-50 p-3 text-sm text-rose-800">{p.error}</div>}</CardContent></Card>
    <History records={p.history} query={p.historyQuery} setQuery={p.setHistoryQuery} status={p.historyStatus} setStatus={p.setHistoryStatus} from={p.from} setFrom={p.setFrom} to={p.to} setTo={p.setTo} reset={() => { p.setHistoryQuery(""); p.setHistoryStatus("todos"); p.setFrom(""); p.setTo("") }} preview={p.setPreview} />
    {p.preview && <DocumentPreview record={p.preview} close={() => p.setPreview(null)} />}{p.crossOpen && <PosInvoiceCross records={p.posInvoices} query={p.crossQuery} setQuery={p.setCrossQuery} select={p.selectPosInvoice} close={() => p.setCrossOpen(false)} />}{p.productSearchOpen && <ProductSearchModal products={p.products} query={p.query} setQuery={p.setQuery} add={p.addProductById} close={() => { p.setProductSearchOpen(false); p.setQuery("") }} />}
  </div>
}

function ProductSearchModal({ products, query, setQuery, add, close }: { products: ProductMaster[]; query: string; setQuery: (value: string) => void; add: (id: string) => void; close: () => void }) { return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-sm"><Card className="flex max-h-[92vh] w-full max-w-5xl flex-col overflow-hidden"><div className="flex items-center justify-between border-b p-4"><div><h2 className="text-lg font-bold">Buscar productos y servicios</h2><p className="text-sm text-muted-foreground">Los resultados cambian automáticamente mientras escribes.</p></div><Button size="icon" variant="ghost" onClick={close}><X className="h-4 w-4" /></Button></div><CardContent className="flex min-h-0 flex-1 flex-col gap-4 p-4"><div className="relative"><Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-primary" /><Input autoFocus className="h-11 pl-11 text-base" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Escribe referencia, código, descripción, marca o código de barras..." /></div><div className="flex items-center justify-between text-xs text-muted-foreground"><span>{products.length} resultado(s)</span><span>Selecciona el producto que deseas adicionar</span></div><div className="min-h-0 flex-1 overflow-y-auto rounded-lg border"><div className="divide-y">{products.map((product) => { const image = product.images.find(Boolean); return <button type="button" key={product.id} onClick={() => add(product.id)} className="grid w-full grid-cols-[64px_1fr_auto] items-center gap-4 p-3 text-left transition-colors hover:bg-cyan-50 focus:bg-cyan-50 focus:outline-none"><div className="flex h-14 w-14 items-center justify-center overflow-hidden rounded-lg border bg-white">{image ? <img src={image} alt={product.name} className="h-full w-full object-contain p-1" /> : <Package className="h-7 w-7 text-muted-foreground/50" />}</div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-xs font-bold text-primary">{product.reference}</span><Badge variant="outline">SKU {product.sku}</Badge>{product.barcodes[0]?.code && <Badge variant="secondary">Cod. barras {product.barcodes[0].code}</Badge>}</div><p className="mt-1 truncate font-semibold">{product.name}</p><p className="mt-1 text-xs text-muted-foreground">{product.brand} · {product.line} · {product.unit} · Stock {product.stock}</p></div><div className="text-right"><p className="text-base font-bold">${money(product.price)}</p><span className="mt-2 inline-flex items-center gap-1 text-xs font-semibold text-primary"><Plus className="h-3.5 w-3.5" />Agregar</span></div></button>})}{!products.length && <div className="flex h-48 flex-col items-center justify-center text-center text-muted-foreground"><Search className="mb-3 h-8 w-8" /><p className="font-medium">No se encontraron productos</p><p className="mt-1 text-xs">Prueba con otra referencia, descripción o código de barras.</p></div>}</div></div></CardContent></Card></div> }

function PosLineTable({ lines, selectedLineId, selectLine, patchLine, remove }: { lines: Line[]; selectedLineId: string; selectLine: (id: string) => void; patchLine: (id: string, patch: Partial<Line>) => void; remove: (id: string) => void }) { return <Card className="overflow-hidden"><div className="overflow-x-auto"><Table><TableHeader><TableRow className="bg-slate-100"><TableHead>Referencia</TableHead><TableHead className="min-w-72">Detalle</TableHead><TableHead>Und/Pres.</TableHead><TableHead className="w-24">Cantidad</TableHead><TableHead className="w-24">Dto. %</TableHead><TableHead className="w-36">Vr. unitario</TableHead><TableHead className="text-right">Total</TableHead><TableHead /></TableRow></TableHeader><TableBody>{lines.map((line) => <TableRow key={line.id} onClick={() => selectLine(line.id)} className={`cursor-pointer transition-colors ${selectedLineId === line.id ? "bg-cyan-50 ring-1 ring-inset ring-cyan-300" : "hover:bg-muted/40"}`}><TableCell className="font-mono font-semibold">{line.code}</TableCell><TableCell>{line.description}</TableCell><TableCell>{line.unitCode}</TableCell><TableCell><Input type="number" min="0.001" step="0.001" value={line.quantity} onFocus={() => selectLine(line.id)} onChange={(e) => patchLine(line.id, { quantity: Number(e.target.value) })} /></TableCell><TableCell><Input type="number" min="0" max="100" value={line.discount} onFocus={() => selectLine(line.id)} onChange={(e) => patchLine(line.id, { discount: Number(e.target.value) })} /></TableCell><TableCell><Input type="number" min="0" value={line.unitPrice} onFocus={() => selectLine(line.id)} onChange={(e) => patchLine(line.id, { unitPrice: Number(e.target.value) })} /></TableCell><TableCell className="text-right text-base font-bold">${money(line.quantity * line.unitPrice * (1-line.discount/100) * (1+line.taxRate/100))}</TableCell><TableCell><Button size="icon" variant="ghost" onClick={(event) => { event.stopPropagation(); remove(line.id) }}><Trash2 className="h-4 w-4" /></Button></TableCell></TableRow>)}{!lines.length && <TableRow><TableCell colSpan={8} className="h-36 text-center text-muted-foreground"><ShoppingCart className="mx-auto mb-2 h-7 w-7" />Busca y adiciona artículos a la operación POS.</TableCell></TableRow>}</TableBody></Table></div></Card> }

function PosInvoiceCross({ records, query, setQuery, select, close }: { records: BillingRecord[]; query: string; setQuery: (value: string) => void; select: (record: BillingRecord) => void; close: () => void }) { const q = query.trim().toLowerCase(); const filtered = [...records].reverse().filter((record) => !q || [record.prefix + record.number, record.customer.id, record.customer.name, record.date].some((value) => value.toLowerCase().includes(q))); return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4 backdrop-blur-sm"><Card className="max-h-[92vh] w-full max-w-6xl overflow-hidden"><div className="flex items-center justify-between border-b p-4"><div><div className="flex items-center gap-2"><RotateCcw className="h-5 w-5 text-amber-600" /><h2 className="text-lg font-bold">Cruce de facturas POS</h2></div><p className="text-sm text-muted-foreground">Selecciona la factura original para cargar y editar los artículos a devolver.</p></div><Button size="icon" variant="ghost" onClick={close}><X className="h-4 w-4" /></Button></div><CardContent className="space-y-4 overflow-y-auto p-4"><div className="relative"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input autoFocus className="pl-9" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar número, fecha, identificación o cliente..." /></div><div className="overflow-x-auto rounded-lg border"><Table><TableHeader><TableRow className="bg-muted/40"><TableHead>Factura POS</TableHead><TableHead>Fecha</TableHead><TableHead>Cliente</TableHead><TableHead>Identificación</TableHead><TableHead className="text-right">Ítems</TableHead><TableHead className="text-right">Valor total</TableHead><TableHead>Estado</TableHead><TableHead /></TableRow></TableHeader><TableBody>{filtered.map((record) => <TableRow key={record.id}><TableCell className="font-mono font-bold">{record.prefix}-{record.number}</TableCell><TableCell>{record.date}</TableCell><TableCell>{record.customer.name}</TableCell><TableCell>{record.customer.id}</TableCell><TableCell className="text-right">{record.lines.length}</TableCell><TableCell className="text-right font-bold">${money(recordTotal(record))}</TableCell><TableCell><Badge variant="secondary">{record.status}</Badge></TableCell><TableCell className="text-right"><Button size="sm" onClick={() => select(record)}><RotateCcw className="mr-2 h-4 w-4" />Cruzar</Button></TableCell></TableRow>)}{!filtered.length && <TableRow><TableCell colSpan={8} className="h-40 text-center text-muted-foreground">No se encontraron facturas POS emitidas.</TableCell></TableRow>}</TableBody></Table></div></CardContent></Card></div> }

function LineTable({ lines, patchLine, remove }: { lines: Line[]; patchLine: (id: string, patch: Partial<Line>) => void; remove: (id: string) => void }) { return <Card className="overflow-hidden"><div className="overflow-x-auto"><Table><TableHeader><TableRow className="bg-muted/40"><TableHead>Código</TableHead><TableHead className="min-w-64">Descripción</TableHead><TableHead>U/M DIAN</TableHead><TableHead className="w-24">Cantidad</TableHead><TableHead className="w-36">Valor unitario</TableHead><TableHead className="w-24">Dto. %</TableHead><TableHead className="w-28">IVA</TableHead><TableHead className="text-right">Total</TableHead><TableHead /></TableRow></TableHeader><TableBody>{lines.map((l) => { const total = l.quantity * l.unitPrice * (1 - l.discount / 100) * (1 + l.taxRate / 100); return <TableRow key={l.id}><TableCell className="font-mono">{l.code}</TableCell><TableCell><Input value={l.description} onChange={(e) => patchLine(l.id, { description: e.target.value })} /></TableCell><TableCell><Input value={l.unitCode} onChange={(e) => patchLine(l.id, { unitCode: e.target.value })} /></TableCell><TableCell><Input type="number" min="0.001" step="0.001" value={l.quantity} onChange={(e) => patchLine(l.id, { quantity: Number(e.target.value) })} /></TableCell><TableCell><Input type="number" min="0" value={l.unitPrice} onChange={(e) => patchLine(l.id, { unitPrice: Number(e.target.value) })} /></TableCell><TableCell><Input type="number" min="0" max="100" value={l.discount} onChange={(e) => patchLine(l.id, { discount: Number(e.target.value) })} /></TableCell><TableCell><SelectField value={String(l.taxRate)} setValue={(v) => patchLine(l.id, { taxRate: Number(v) })} options={[["0", "0%"], ["5", "5%"], ["19", "19%"]]} /></TableCell><TableCell className="text-right font-semibold">${money(total)}</TableCell><TableCell><Button size="icon" variant="ghost" onClick={() => remove(l.id)}><Trash2 className="h-4 w-4" /></Button></TableCell></TableRow>})}{!lines.length && <TableRow><TableCell colSpan={9} className="h-40 text-center text-muted-foreground">Agrega los bienes o servicios del documento.</TableCell></TableRow>}</TableBody></Table></div></Card> }
function Totals({ subtotal, discounts, taxes, total }: { subtotal: number; discounts: number; taxes: number; total: number }) { return <Card><CardContent className="space-y-3 p-5"><Amount label="Subtotal" value={subtotal} /><Amount label="Descuentos" value={-discounts} /><Amount label="IVA" value={taxes} /><div className="border-t pt-3"><Amount label="Total a pagar" value={total} strong /></div></CardContent></Card> }
function Amount({ label, value, strong }: { label: string; value: number; strong?: boolean }) { return <div className={`flex justify-between ${strong ? "text-lg font-bold" : "text-sm"}`}><span>{label}</span><span>${money(value)}</span></div> }
function DianItem({ label, value, warning }: { label: string; value: string; warning?: boolean }) { return <div className="flex gap-3 rounded-lg border p-4"><span className={`rounded-lg p-2 ${warning ? "bg-amber-50 text-amber-700" : "bg-emerald-50 text-emerald-700"}`}>{warning ? <ShieldCheck className="h-5 w-5" /> : <CheckCircle2 className="h-5 w-5" />}</span><div><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div></div> }
function History({ records, query, setQuery, status, setStatus, from, setFrom, to, setTo, reset, preview }: { records: BillingRecord[]; query: string; setQuery: (v: string) => void; status: string; setStatus: (v: string) => void; from: string; setFrom: (v: string) => void; to: string; setTo: (v: string) => void; reset: () => void; preview: (r: BillingRecord) => void }) { return <section className="space-y-3"><div><h2 className="text-lg font-bold">Historial de documentos</h2><p className="text-sm text-muted-foreground">Consulta, descarga y reimpresión de documentos generados.</p></div><Card><CardContent className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-[1fr_190px_150px_150px_auto]"><div className="relative"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input className="pl-9" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar número, adquirente, identificación u origen..." /></div><SelectField value={status} setValue={setStatus} options={[["todos", "Todos los estados"], ["Borrador", "Borrador"], ["Pendiente de envío DIAN", "Pendiente de envío DIAN"], ["Validado DIAN", "Validado DIAN"], ["Rechazado DIAN", "Rechazado DIAN"]]} /><Input aria-label="Fecha inicial" type="date" value={from} onChange={(e) => setFrom(e.target.value)} /><Input aria-label="Fecha final" type="date" value={to} onChange={(e) => setTo(e.target.value)} /><Button variant="outline" onClick={reset}><FilterX className="h-4 w-4" /></Button></CardContent></Card><Card className="overflow-hidden"><div className="overflow-x-auto"><Table><TableHeader><TableRow className="bg-muted/40"><TableHead>Documento</TableHead><TableHead>Fecha</TableHead><TableHead>Adquirente</TableHead><TableHead>Identificación</TableHead><TableHead className="text-right">Total</TableHead><TableHead>Estado</TableHead><TableHead className="text-right">Acciones</TableHead></TableRow></TableHeader><TableBody>{records.map((r) => <TableRow key={r.id}><TableCell className="font-mono font-semibold">{r.prefix}-{r.number}</TableCell><TableCell>{r.date}</TableCell><TableCell>{r.customer.name}</TableCell><TableCell>{r.customer.id}</TableCell><TableCell className="text-right font-semibold">${money(recordTotal(r))}</TableCell><TableCell><Badge variant="secondary" className={r.status.includes("Pendiente") ? "bg-amber-50 text-amber-800" : ""}>{r.status}</Badge></TableCell><TableCell><div className="flex justify-end gap-1"><Button size="sm" variant="outline" onClick={() => preview(r)}><Eye className="mr-1 h-4 w-4" />Ver</Button><Button size="icon" variant="ghost" onClick={() => printRecord(r)} title="Imprimir"><Printer className="h-4 w-4" /></Button><Button size="icon" variant="ghost" onClick={() => downloadHtml(r)} title="Descargar formato"><Download className="h-4 w-4" /></Button><Button size="icon" variant="ghost" onClick={() => downloadXml(r)} title="Descargar XML"><FileCode2 className="h-4 w-4" /></Button></div></TableCell></TableRow>)}{!records.length && <TableRow><TableCell colSpan={7} className="h-36 text-center text-muted-foreground">No hay documentos para los filtros aplicados.</TableCell></TableRow>}</TableBody></Table></div></Card></section> }
function DocumentPreview({ record, close }: { record: BillingRecord; close: () => void }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-3 backdrop-blur-sm"><div className="flex max-h-[95vh] w-full max-w-4xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b p-3"><div><p className="font-bold">Representación gráfica</p><p className="text-xs text-muted-foreground">{record.prefix}-{record.number}</p></div><div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => downloadHtml(record)}><Download className="mr-2 h-4 w-4" />Descargar</Button><Button size="sm" onClick={() => printRecord(record)}><Printer className="mr-2 h-4 w-4" />Imprimir</Button><Button size="icon" variant="ghost" onClick={close}><X className="h-4 w-4" /></Button></div></div><iframe title="Vista previa del documento" className="min-h-0 flex-1 bg-slate-100" srcDoc={documentHtml(record)} /></div></div> }
function Field({ label, children, wide }: { label: string; children: React.ReactNode; wide?: boolean }) { return <div className={`space-y-1.5 ${wide ? "md:col-span-2" : ""}`}><Label>{label}</Label>{children}</div> }
function SelectField({ value, setValue, options }: { value: string; setValue: (v: string) => void; options: string[][] }) { return <Select value={value} onValueChange={(v) => v && setValue(v)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{options.map(([v, label]) => <SelectItem key={v} value={v}>{label}</SelectItem>)}</SelectContent></Select> }
function money(value: number) { return new Intl.NumberFormat("es-CO", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value || 0) }
function recordTotal(r: BillingRecord) { return r.lines.reduce((sum, l) => sum + l.quantity * l.unitPrice * (1 - l.discount / 100) * (1 + l.taxRate / 100), 0) }
function escapeHtml(text: string) { return text.replace(/[&<>'"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[c]!) }
function invoiceDocumentHtml(r: BillingRecord) { const cfg = settings[r.kind]; const subtotal = r.lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0); const discount = r.lines.reduce((s, l) => s + l.quantity * l.unitPrice * l.discount / 100, 0); const tax = r.lines.reduce((s, l) => s + l.quantity * l.unitPrice * (1 - l.discount / 100) * l.taxRate / 100, 0); const total = subtotal - discount + tax; const rows = r.lines.map((l) => `<tr><td>${escapeHtml(l.code)}</td><td>${escapeHtml(l.description)}</td><td>${l.quantity}</td><td>$${money(l.unitPrice)}</td><td>${l.discount}%</td><td>${l.taxRate}%</td><td>$${money(l.quantity * l.unitPrice * (1-l.discount/100)*(1+l.taxRate/100))}</td></tr>`).join(""); const qr = Array.from({length: 100}, (_, i) => `<i style="background:${parseInt(r.uniqueCode[i % r.uniqueCode.length],16)%2 ? '#111':'#fff'}"></i>`).join(""); return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${cfg.documentName} ${r.prefix}-${r.number}</title><style>body{font-family:Arial,sans-serif;color:#172033;margin:0;padding:28px;font-size:12px}.sheet{max-width:820px;margin:auto}.head{display:flex;justify-content:space-between;gap:24px;border-bottom:3px solid #123d67;padding-bottom:16px}.brand{font-size:26px;font-weight:800;color:#123d67}.title{text-align:right}h1{font-size:17px;margin:0 0 5px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.box{border:1px solid #ccd5df;border-radius:6px;padding:10px}.label{font-size:9px;text-transform:uppercase;color:#667085}table{width:100%;border-collapse:collapse;margin-top:12px}th{background:#123d67;color:white;text-align:left;padding:7px}td{border-bottom:1px solid #d8dee6;padding:7px}.totals{width:310px;margin:14px 0 14px auto}.totals div{display:flex;justify-content:space-between;padding:4px}.grand{border-top:2px solid #123d67;font-size:15px;font-weight:800}.footer{display:flex;gap:18px;border-top:1px solid #ccd5df;padding-top:14px}.qr{display:grid;grid-template-columns:repeat(10,5px);grid-auto-rows:5px;border:5px solid white;box-shadow:0 0 0 1px #aaa;width:max-content}.code{word-break:break-all;font-family:monospace;font-size:9px}.note{background:#f1f5f9;padding:8px;margin-top:10px}@media print{body{padding:0}.no-print{display:none}}</style></head><body><div class="sheet"><div class="head"><div><div class="brand">FERREIA</div><b>${company.name}</b><br>NIT ${company.nit}-${company.dv}<br>${company.address} · ${company.city}<br>${company.email} · ${company.phone}<br>${company.regime} · ${company.responsibility}</div><div class="title"><h1>${cfg.documentName}</h1><b>${r.prefix}-${r.number}</b><br>Fecha: ${r.date} ${r.time}<br>Moneda: ${r.currency}<br><b>Estado: ${r.status}</b></div></div><div class="grid"><div class="box"><span class="label">Adquirente</span><br><b>${escapeHtml(r.customer.name)}</b><br>${r.customer.idType}: ${escapeHtml(r.customer.id)}${r.customer.dv ? '-'+escapeHtml(r.customer.dv):''}<br>${escapeHtml(r.customer.address)} · ${escapeHtml(r.customer.email)}<br>${escapeHtml(r.customer.fiscalResponsibility)} · ${escapeHtml(r.customer.taxRegime)}</div><div class="box"><span class="label">Información del documento</span><br>Forma de pago: ${r.paymentForm === '1' ? 'Contado':'Crédito'}<br>Medio de pago DIAN: ${escapeHtml(r.paymentMethod)}<br>${r.originalNumber ? `Documento origen: <b>${escapeHtml(r.originalNumber)}</b><br>`:''}Resolución: ${configuration.invoice.resolution}<br>Rango: ${configuration.invoice.range}</div></div><table><thead><tr><th>Código</th><th>Descripción</th><th>Cant.</th><th>Vr. unitario</th><th>Dto.</th><th>IVA</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><div><span>Subtotal</span><b>$${money(subtotal)}</b></div><div><span>Descuentos</span><b>-$${money(discount)}</b></div><div><span>IVA</span><b>$${money(tax)}</b></div><div class="grand"><span>Total</span><span>$${money(total)}</span></div></div>${r.notes ? `<div class="note"><b>Observaciones:</b> ${escapeHtml(r.notes)}</div>`:''}<div class="footer"><div class="qr">${qr}</div><div><b>${cfg.code}</b><div class="code">${r.uniqueCode}</div><br><span class="label">Representación gráfica de la factura electrónica de venta</span><br>Fabricante del software: FERREIA ERP · Documento preparado para validación DIAN.<br><br>Fecha de generación: ${r.createdAt.slice(0,19).replace('T',' ')}</div></div></div></body></html>` }

function documentHtml(r: BillingRecord) { return r.kind === "pos" || r.kind === "pos-return" ? posDocumentHtml(r) : invoiceDocumentHtml(r).replace("<style>", "<style>@page{size:Letter;margin:12mm}") }
function posDocumentHtml(r: BillingRecord) { const cfg = settings[r.kind]; const subtotal = r.lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0); const discount = r.lines.reduce((s, l) => s + l.quantity * l.unitPrice * l.discount / 100, 0); const tax = r.lines.reduce((s, l) => s + l.quantity * l.unitPrice * (1-l.discount/100) * l.taxRate/100, 0); const total = subtotal-discount+tax; const method: Record<string,string> = { "10":"EFECTIVO", "42":"CONSIGNACIÓN", "47":"TRANSFERENCIA", "48":"TARJETA CRÉDITO", "49":"TARJETA DÉBITO", ZZZ:"OTRO" }; const rows = r.lines.map((l) => `<div class="item"><div><b>${l.quantity}</b> |${escapeHtml(l.code)} ${escapeHtml(l.description)}</div><div class="numbers"><span>$${money(l.unitPrice)}</span><span>Dto ${l.discount}%</span><b>$${money(l.quantity*l.unitPrice*(1-l.discount/100)*(1+l.taxRate/100))}</b><span>IVA ${l.taxRate}%</span></div></div>`).join(""); const qr = Array.from({length: 225},(_,i)=>`<i style="background:${parseInt(r.uniqueCode[i%r.uniqueCode.length],16)%2?'#111':'#fff'}"></i>`).join(""); return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${cfg.documentName} ${r.prefix}-${r.number}</title><style>@page{size:80mm auto;margin:3mm}*{box-sizing:border-box}html,body{margin:0;padding:0;background:#fff;color:#111}body{font:10px/1.35 "Courier New",monospace}.ticket{width:74mm;margin:0 auto;padding:2mm 1mm;text-align:left}.center{text-align:center}.company{font-size:13px;font-weight:bold}.rule{border-top:1px dashed #111;margin:7px 0}.title{font-size:10px;font-weight:bold;text-align:center;text-transform:uppercase}.item{padding:5px 0;border-bottom:1px dashed #777}.numbers{display:grid;grid-template-columns:1fr 1fr;gap:2px 6px;text-align:right;margin-top:3px}.summary{margin:7px 0}.row{display:flex;justify-content:space-between;gap:8px}.total{font-size:14px;font-weight:bold;border-top:1px dashed #111;border-bottom:1px dashed #111;padding:5px 0;margin:6px 0}.code{word-break:break-all;font-size:8px}.qr{display:grid;grid-template-columns:repeat(15,4px);grid-auto-rows:4px;width:max-content;margin:8px auto;border:5px solid #fff;box-shadow:0 0 0 1px #111}.legal{text-align:center;font-size:8px;line-height:1.35;margin-top:7px}@media screen{body{background:#e9eef1;padding:18px}.ticket{background:white;box-shadow:0 4px 24px #0002}}@media print{body{background:white;padding:0}.ticket{box-shadow:none}}</style></head><body><main class="ticket"><div class="center"><div class="company">${company.name}</div>NIT ${company.nit}-${company.dv}<br>${company.regime}<br>${company.address}<br>${company.city}<br>Tel. ${company.phone}<br>${company.email}</div><div class="rule"></div><div class="title">${cfg.documentName}</div><div class="center"><b>No. ${r.prefix}-${r.number}</b></div><div class="rule"></div>Fecha: ${r.date} Hora: ${r.time}<br>Adquirente: ${escapeHtml(r.customer.name)}<br>Identificación: ${escapeHtml(r.customer.id)}${r.customer.dv?'-'+escapeHtml(r.customer.dv):''}${r.originalNumber?`<br>Documento origen: <b>${escapeHtml(r.originalNumber)}</b>`:''}<div class="rule"></div><b>CANT | REF. DESCRIPCIÓN</b>${rows}<div class="summary"><div class="row"><span># Ítems</span><b>${r.lines.length}</b></div><div class="row"><span>Subtotal</span><span>$${money(subtotal)}</span></div><div class="row"><span>Descuentos</span><span>-$${money(discount)}</span></div><div class="row"><span>IVA</span><span>$${money(tax)}</span></div><div class="row total"><span>TOTAL</span><span>$${money(total)}</span></div></div><div class="title">IMPUESTOS</div>${[...new Set(r.lines.map(l=>l.taxRate))].map(rate=>{const base=r.lines.filter(l=>l.taxRate===rate).reduce((s,l)=>s+l.quantity*l.unitPrice*(1-l.discount/100),0);return `<div class="row"><span>IVA ${rate}% Base $${money(base)}</span><span>$${money(base*rate/100)}</span></div>`}).join('')}<div class="rule"></div><div class="title">FORMAS DE PAGO</div><div class="row"><span>${r.paymentForm==='1'?'CONTADO':'CRÉDITO'} ${method[r.paymentMethod]??r.paymentMethod}</span><b>$${money(total)}</b></div><div class="rule"></div>Representación gráfica del documento equivalente electrónico POS.<br>Resolución DIAN: ${configuration.pos.resolution}<br>Rango: ${configuration.pos.range}<br>Vigencia: ${configuration.pos.validUntil}<br><br><b>${cfg.code}</b><div class="code">${r.uniqueCode}</div><br>Fecha de generación: ${r.createdAt.slice(0,19).replace('T',' ')}${r.notes?`<div class="rule"></div>${escapeHtml(r.notes)}`:''}<div class="legal">CONSERVE ESTE DOCUMENTO<br>Gracias por su compra<br>La validez fiscal definitiva depende de la respuesta de validación de la DIAN.</div><div class="qr">${qr}</div></main></body></html>` }
function printRecord(r: BillingRecord) { const w = window.open("", "_blank", "width=920,height=760"); if (!w) return; w.document.write(documentHtml(r)); w.document.close(); w.focus(); setTimeout(() => w.print(), 250) }
function download(name: string, content: string, type: string) { const url = URL.createObjectURL(new Blob([content], { type })); const a = document.createElement("a"); a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url) }
function downloadHtml(r: BillingRecord) { download(`${r.prefix}-${r.number}.html`, documentHtml(r), "text/html;charset=utf-8") }
function downloadXml(r: BillingRecord) { const cfg = settings[r.kind]; const xml = `<?xml version="1.0" encoding="UTF-8"?>\n<DocumentoElectronico simulacion="true"><Tipo>${cfg.documentName}</Tipo><Numero>${r.prefix}-${r.number}</Numero><Fecha>${r.date}T${r.time}</Fecha><Emisor nit="${company.nit}" dv="${company.dv}">${company.name}</Emisor><Adquirente tipo="${r.customer.idType}" numero="${escapeHtml(r.customer.id)}">${escapeHtml(r.customer.name)}</Adquirente><${cfg.code}>${r.uniqueCode}</${cfg.code}><Total moneda="${r.currency}">${recordTotal(r).toFixed(2)}</Total><Estado>${r.status}</Estado></DocumentoElectronico>`; download(`${r.prefix}-${r.number}.xml`, xml, "application/xml;charset=utf-8") }
